-- seed/faqs.sql
-- Populates public.faqs with the customer-facing FAQ list maintained by
-- the BidaWash team. Source of truth is docs/faqs.csv — regenerate this
-- file when the CSV changes.
--
-- Re-runnable: `on conflict (id) do update` upserts each row, so pasting
-- this into the Supabase SQL editor repeatedly is safe. Rows removed
-- from the CSV are NOT auto-deleted here; delete them by hand or drop
-- and re-run the whole seed.
--
-- Requires migration 0003_favorites_and_faqs.sql (which creates the
-- public.faqs table and its RLS policy).

on conflict (id) do update set
  question   = excluded.question,
  answer     = excluded.answer,
  category   = excluded.category,
  sort_order = excluded.sort_order;
